{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "CZC25146, a close-transfer kinase inhibitor with morpholine and anilino-pyrimidine motifs, showed negligible total brain/plasma AUC in mice, indicating poor CNS access for a molecule with similar polar and aromatic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SSR149415, a large lipophilic sulfonamide/lactam, exhibited low BBB penetration and brain uptake in non-human primates by PET, directly demonstrating that high lipophilicity and size can still yield poor CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Compound 18a, containing a dichlorophenyl pyrazole and amide, showed little to no CNS penetration with a very low brain:plasma ratio in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Compound 9, a chlorophenyl heteroaromatic piperidine, gave brain-to-plasma ratios of 0.01-0.07 after oral dosing in rats, consistent with minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Compound 17a, a dichlorophenyl pyrazole piperidine urea, demonstrated little to no CNS penetration in an in vivo PK assay.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "AZ10419369, despite being an ABC-transporter substrate with low rodent brain uptake, showed rapid high brain uptake in humans (3-4% injected dose in brain), showing that efflux liability alone does not preclude meaningful CNS access in primates.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Methylamine 18c achieved a rat brain:plasma ratio of 0.31 and was classified as permeable, providing moderate evidence that some large, lipophilic amides can cross the BBB.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query's very high molecular weight, TPSA, HBA count, and rotatable bond count predict poor passive BBB diffusion, and the most transferable experimental analogues with similar lipophilic heteroaromatic/piperazine/dichlorophenyl scaffolds show negligible-to-low CNS exposure. The strongest counterevidence (AZ10419369) shows that efflux substrates can still enter primate brain, but its much smaller, CNS-optimized structure limits transfer to this large query.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or PET data are available for the query molecule itself.",
    "Rodent-to-primate differences in efflux transporter activity may alter CNS exposure predictions.",
    "Unbound brain concentrations and target-site exposure are unknown.",
    "The exact transporter substrate status of the query has not been experimentally determined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

